import React, { useState, useEffect } from "react"; // 1. useEffect add kiya
import { Link } from "react-router-dom";

const Menu = () => {
  const [selectedMenu, setSelectedMenu] = useState(0);
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);
  const [userName, setUserName] = useState("USERID"); // 2. State banayi user ke liye

  useEffect(() => {
    // 3. URL se naam check karein (Login.js se jo aa raha hai)
    const queryParams = new URLSearchParams(window.location.search);
    const nameFromUrl = queryParams.get("user");

    if (nameFromUrl) {
      setUserName(nameFromUrl);
      localStorage.setItem("user", nameFromUrl); // Port 3000 par save kar diya
    } else {
      // Agar URL mein nahi hai toh localStorage se uthao
      const savedUser = localStorage.getItem("user");
      if (savedUser) setUserName(savedUser);
    }
  }, []);

  const handleMenuClick = (index) => {
    setSelectedMenu(index);
  };

  const handleProfileClick = () => {
    setIsProfileDropdownOpen(!isProfileDropdownOpen);
  };

  const handleLogout = () => {
    localStorage.removeItem("user");
    alert("Logged out successfully!");
    window.location.href = "http://localhost:3001"; 
  };

  const menuClass = "menu";
  const activeMenuClass = "menu selected";

  return (
    <div className="menu-container">
      <img src="logo.png" alt="Logo" style={{ width: "50px" }} />
      <div className="menus">
        <ul>
          <li>
            <Link style={{ textDecoration: "none" }} to="/" onClick={() => handleMenuClick(0)}>
              <p className={selectedMenu === 0 ? activeMenuClass : menuClass} style={{ marginTop: "30px" }}>
                Dashboard
              </p>
            </Link>
          </li>
          <li>
            <Link style={{ textDecoration: "none" }} to="/orders" onClick={() => handleMenuClick(1)}>
              <p className={selectedMenu === 1 ? activeMenuClass : menuClass}>Orders</p>
            </Link>
          </li>
          <li>
            <Link style={{ textDecoration: "none" }} to="/holdings" onClick={() => handleMenuClick(2)}>
              <p className={selectedMenu === 2 ? activeMenuClass : menuClass}>Holdings</p>
            </Link>
          </li>
          <li>
            <Link style={{ textDecoration: "none" }} to="/positions" onClick={() => handleMenuClick(3)}>
              <p className={selectedMenu === 3 ? activeMenuClass : menuClass}>Positions</p>
            </Link>
          </li>
          <li>
            <Link style={{ textDecoration: "none" }} to="/funds" onClick={() => handleMenuClick(4)}>
              <p className={selectedMenu === 4 ? activeMenuClass : menuClass}>Funds</p>
            </Link>
          </li>
          <li>
            <Link style={{ textDecoration: "none" }} to="/apps" onClick={() => handleMenuClick(6)}>
              <p className={selectedMenu === 6 ? activeMenuClass : menuClass}>Apps</p>
            </Link>
          </li>
        </ul>
        <hr />

        <div className="profile" onClick={handleProfileClick} style={{ cursor: "pointer", position: "relative" }}>
          <div className="avatar" style={{ 
            backgroundColor: "#387ed1", 
            color: "white", 
            borderRadius: "50%", 
            width: "35px", 
            height: "35px", 
            display: "flex", 
            alignItems: "center", 
            justifyContent: "center",
            fontWeight: "bold"
          }}>
            {userName !== "USERID" ? userName.charAt(0).toUpperCase() : "U"}
          </div>
          <p className="username" style={{ marginTop: "10px", fontWeight: "500" }}>
            {userName.toUpperCase()}
          </p>
          {isProfileDropdownOpen && (
            <div style={{
              position: "absolute",
              top: "60px",
              right: "0",
              backgroundColor: "white",
              border: "1px solid #eee",
              padding: "10px 20px",
              zIndex: 1000,
              boxShadow: "0px 8px 16px rgba(0,0,0,0.1)",
              borderRadius: "8px"
            }}>
              <button 
                onClick={handleLogout}
                style={{
                  background: "none",
                  border: "none",
                  color: "#d9534f",
                  cursor: "pointer",
                  fontWeight: "600",
                  fontSize: "14px",
                  whiteSpace: "nowrap"
                }}
              >
                <i className="fa fa-sign-out" style={{ marginRight: "8px" }}></i>
                Logout Account
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Menu;
